const d = $json;

if (
  typeof d.clinicalText !== "string" ||
  d.clinicalText.trim().length === 0
) {
  throw new Error(
    "clinical-ai-helper: clinicalText is missing"
  );
}

const knownFacts =
  d.knownFacts &&
  typeof d.knownFacts === "object"
    ? d.knownFacts
    : {};

const unresolvedTerms =
  Array.isArray(d.unresolvedTerms)
    ? d.unresolvedTerms
    : [];

return {
  json: {
    clinicalText:
      d.clinicalText.trim(),

    knownFacts,

    unresolvedTerms
  }
};

const d = $json;

const systemInstruction = `
You are a clinical information extraction assistant.

Extract only facts explicitly supported by the clinical text.

Rules:
1. Do not invent clinical facts.
2. Do not infer current delivery from gravidity or parity.
3. PARA > 0 does not mean the current pregnancy has delivered.
4. Distinguish current pregnancy from prior obstetric history.
5. If evidence is insufficient, return null.
6. Do not create, guess, or output POGS IDs.
7. Do not create categoryId, conditionId, procedureId, stageId, or option IDs.
8. Preserve diagnoses and procedures as clinical concepts/text.
9. Negated findings must be marked as negated.
10. Output only values supported by the provided material.
`.trim();

const userPayload = {
  clinicalText:
    d.clinicalText,

  knownDeterministicFacts:
    d.knownFacts,

  unresolvedTerms:
    d.unresolvedTerms
};

return {
  json: {
    clinicalText:
      d.clinicalText,

    knownFacts:
      d.knownFacts,

    unresolvedTerms:
      d.unresolvedTerms,

    openaiRequest: {
      model:
        "gpt-5-nano",

      store:
        false,

      input: [
        {
          role:
            "system",

          content: [
            {
              type:
                "input_text",

              text:
                systemInstruction
            }
          ]
        },
        {
          role:
            "user",

          content: [
            {
              type:
                "input_text",

              text:
                JSON.stringify(
                  userPayload,
                  null,
                  2
                )
            }
          ]
        }
      ],

      text: {
        format: {
          type:
            "json_schema",

          name:
            "clinical_extraction",

          strict:
            true,

          schema: {
            type:
              "object",

            additionalProperties:
              false,

            properties: {
              isPregnancy: {
                type: [
                  "boolean",
                  "null"
                ]
              },

              isGyne: {
                type: [
                  "boolean",
                  "null"
                ]
              },

              isPostpartum: {
                type: [
                  "boolean",
                  "null"
                ]
              },

              currentPregnancyDelivered: {
                type: [
                  "boolean",
                  "null"
                ]
              },

              pregnancyTypeText: {
                type: [
                  "string",
                  "null"
                ]
              },

              deliveryMannerText: {
                type: [
                  "string",
                  "null"
                ]
              },

              deliveryEvidence: {
                type:
                  "array",

                items: {
                  type:
                    "string"
                }
              },

              diagnosisTerms: {
                type:
                  "array",

                items: {
                  type:
                    "object",

                  additionalProperties:
                    false,

                  properties: {
                    term: {
                      type:
                        "string"
                    },

                    negated: {
                      type:
                        "boolean"
                    },

                    evidence: {
                      type:
                        "string"
                    }
                  },

                  required: [
                    "term",
                    "negated",
                    "evidence"
                  ]
                }
              },

              comorbidityTerms: {
                type:
                  "array",

                items: {
                  type:
                    "object",

                  additionalProperties:
                    false,

                  properties: {
                    term: {
                      type:
                        "string"
                    },

                    negated: {
                      type:
                        "boolean"
                    },

                    evidence: {
                      type:
                        "string"
                    }
                  },

                  required: [
                    "term",
                    "negated",
                    "evidence"
                  ]
                }
              },

              procedureTerms: {
                type:
                  "array",

                items: {
                  type:
                    "object",

                  additionalProperties:
                    false,

                  properties: {
                    term: {
                      type:
                        "string"
                    },

                    evidence: {
                      type:
                        "string"
                    }
                  },

                  required: [
                    "term",
                    "evidence"
                  ]
                }
              },

              uncertainFacts: {
                type:
                  "array",

                items: {
                  type:
                    "string"
                }
              }
            },

            required: [
              "isPregnancy",
              "isGyne",
              "isPostpartum",
              "currentPregnancyDelivered",
              "pregnancyTypeText",
              "deliveryMannerText",
              "deliveryEvidence",
              "diagnosisTerms",
              "comorbidityTerms",
              "procedureTerms",
              "uncertainFacts"
            ]
          }
        }
      }
    }
  }
};

const response = $json;

if (!response.id) {
  throw new Error(
    "OpenAI response has no response ID"
  );
}

if (
  response.status !== undefined &&
  response.status !== "completed"
) {
  throw new Error(
    `OpenAI response did not complete. Status: ${
      response.status
    }`
  );
}

if (
  !Array.isArray(
    response.output
  )
) {
  throw new Error(
    "OpenAI response has no output array"
  );
}

return {
  json:
    response
};

const response = $json;

const contentItems =
  (response.output ?? [])
    .flatMap(
      outputItem =>
        outputItem.content ?? []
    );

const outputText =
  contentItems.find(
    item =>
      item.type === "output_text"
  );

if (!outputText?.text) {
  throw new Error(
    "OpenAI response contains no output_text"
  );
}

let aiFacts;

try {
  aiFacts =
    JSON.parse(
      outputText.text
    );
} catch (error) {
  throw new Error(
    `Failed to parse AI output: ${
      error.message
    }`
  );
}

return {
  json: {
    aiFacts,

    aiMeta: {
      used:
        true,

      model:
        response.model ??
        null,

      responseId:
        response.id ??
        null
    }
  }
};
